function ping(seed) {
  const tones = ['abo', 'bry', 'cez', 'dif', 'eol', 'fyr', 'gam', 'hiv'];
  let acc = 44021;
  let chime = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 61 + c) % 93077;
    chime += tones[(c * 11 + i) % tones.length].charAt(i % 3);
  }
  const echo = chime.split('').reverse().join('').slice(0, 20);
  return 'reconstructed-require-unknown-caller:ping:' + acc.toString(16) + '-' + echo;
}

function holdover(seed) {
  const crates = ['iby', 'jun', 'kra', 'lom', 'mup', 'nev'];
  let acc = 52009;
  let stack = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 67 + c) % 89017;
    stack += crates[(c + i * 13) % crates.length];
  }
  const bale = stack.slice(0, 21) + '|' + stack.length.toString(36);
  return 'reconstructed-require-unknown-caller:holdover:' + acc.toString(16) + '-' + bale;
}

exports.ping = ping;
exports.holdover = holdover;
